PALEY_EV = {4457: 'Input check done here: omega(Q_4457) = 15. A K15 was found and checked edge by edge, and clique.c and gen0 both find no K16 on all 557 reduced subproblems (affine automorphisms x -> ax+b with a square, so a clique may be taken through edge {0,1}; x -> 1-x fixes {0,1}), about 15 min per checker (logs/paley_omega.jsonl). The doubled graph itself is not checked.'}
PALEY_NOTE = {5501: 'omega(Q_5501) is optional Mac job M4, about 1 h per checker (10 of 687 subproblems took 55 s here).', 8941: 'omega(Q_8941) not checked: LuSL report 80 CPU h (p.112); beyond the one-day criterion.'}
PAL = {'17,17': 4457, '18,18': 5501, '19,19': 8941, '20,20': 10861, '21,21': 15461, '22,22': 19553, '23,23': 24709}
for cell, p in PAL.items():
    b = builds[cell]
    src = S['survey'] + ' Table IIc p.11 [%s] and item 2.2.c; ' % ('LuSL' if p <= 8941 else 'Ex23') + (S['LuSL'] + ' Lemma 1 p.103, Thm 2 pp.112-115' if p <= 8941 else S['ExP']) + '; doubling as stated in ' + S['XXER'] + ' pp.12-13'
    ev = 'n=2p+2=%d (formula; p prime, p = 1 mod 4 checked). Graph built (graph6 writer self-tested identical to round-1 paley_doubling for p=13,101,797 and to repo mathon101). ' % b['N']
    ev += PALEY_EV.get(p, '')
    notes = 'Clique bound of the doubled graph = omega(Q_p)+1 by the Shearer/Mathon lemma (proof, not checked on the object); omega(Q_p) = %d is the published value (%s). ' % (b['published_clique_number_of_Q_p'], b['clique_number_source'].split(':')[0])
    notes += PALEY_NOTE.get(p, '')
    if b['N'] > 40000: notes += ' Above 40,000 vertices: no file; exact recipe = (p, vertex order w3,w1,H,H\', rule) in build_paley_doubling.py; graph6 text SHA-256 %s (%d bytes) for regeneration.' % (b['g6_sha256_uncompressed'], b['g6_bytes'])
    row(cell, 2, b['survey_lower'], 'RECIPE_DOCUMENTED', src, ev, notes, file=('build_round2/' + b['file']) if b.get('file') else '', sha=b.get('sha256') or '')

